LOCK TABLE core.customers, core.sellers, core.categories, core.products, core.orders, core.order_items, core.order_payments, core.order_reviews IN SHARE ROW EXCLUSIVE MODE;

INSERT INTO etl.table_stats SELECT current_setting('etl.run_id')::uuid, 'customers', (SELECT COUNT(*) FROM stage_customers), COUNT(*), (SELECT COUNT(*) FROM stage_customers WHERE cardinality(_errors)>0), COUNT(*) FILTER (WHERE c.customer_id IS NULL), COUNT(*) FILTER (WHERE c.customer_id IS NOT NULL AND (ROW(c.customer_unique_id,c.zip_code_prefix,c.city,c.state) IS DISTINCT FROM ROW(s.customer_unique_id,s.zip_code_prefix,s.city,s.state))), COUNT(*) FILTER (WHERE c.customer_id IS NOT NULL AND NOT (ROW(c.customer_unique_id,c.zip_code_prefix,c.city,c.state) IS DISTINCT FROM ROW(s.customer_unique_id,s.zip_code_prefix,s.city,s.state))) FROM stage_customers s LEFT JOIN core.customers c ON c.customer_id=s.customer_id WHERE cardinality(s._errors)=0;

INSERT INTO core.customers AS target (customer_id, customer_unique_id, zip_code_prefix, city, state) SELECT customer_id, customer_unique_id, zip_code_prefix, city, state FROM stage_customers WHERE cardinality(_errors)=0 ON CONFLICT (customer_id) DO UPDATE SET customer_unique_id=excluded.customer_unique_id, zip_code_prefix=excluded.zip_code_prefix, city=excluded.city, state=excluded.state WHERE ROW(target.customer_unique_id,target.zip_code_prefix,target.city,target.state) IS DISTINCT FROM ROW(excluded.customer_unique_id,excluded.zip_code_prefix,excluded.city,excluded.state);

