INSERT INTO etl.table_stats SELECT current_setting('etl.run_id')::uuid, 'order_reviews', (SELECT COUNT(*) FROM stage_order_reviews), COUNT(*), (SELECT COUNT(*) FROM stage_order_reviews WHERE cardinality(_errors)>0), COUNT(*) FILTER (WHERE c.review_id IS NULL), COUNT(*) FILTER (WHERE c.review_id IS NOT NULL AND (ROW(c.review_score,c.comment_title,c.comment_message,c.review_created_at,c.review_answered_at) IS DISTINCT FROM ROW(s.review_score,s.comment_title,s.comment_message,s.review_created_at,s.review_answered_at))), COUNT(*) FILTER (WHERE c.review_id IS NOT NULL AND NOT (ROW(c.review_score,c.comment_title,c.comment_message,c.review_created_at,c.review_answered_at) IS DISTINCT FROM ROW(s.review_score,s.comment_title,s.comment_message,s.review_created_at,s.review_answered_at))) FROM stage_order_reviews s LEFT JOIN core.order_reviews c ON c.review_id=s.review_id AND c.order_id=s.order_id WHERE cardinality(s._errors)=0;

